    return {
      'q_l31_h1':[N('What is the minimal capacity for the nonnegative array?',14,'Capacity13 requires four chunks;14 permits three.'),N('How many chunks does greedy require at capacity 13?',4,'The ten and eight each require their own chunk.'),S('Select all valid conclusions.',
        (True,'With nonnegative values, the greedy longest-prefix rule minimizes chunk count at fixed capacity.','Moving the first cut right cannot increase the nonnegative remaining burden.'),
        (False,'For arbitrary signed values, max(values) is always a valid lower bound on the optimal maximum chunk sum.','[6,−5] can be one chunk of sum1.'),
        (True,'Even with signed values, existence of a feasible partition is monotone in capacity.','Any partition feasible at C remains feasible at a larger C.'),
        (False,'Replacing an invalid greedy predicate with binary search repairs its answers.','Search cannot correct a false feasibility oracle.'),
        (True,'The signed prefix recurrence can supply a correct fixed-capacity oracle.','It considers every possible preceding cut.'))],
      'q_l31_h2':[N('What is the initial one-based select(5) coordinate?',3,'The first three frequencies sum to five.'),N('After removing one −5, what is twice the median?',3,'Middle values are zero and three.'),S('Select all valid statements.',
        (True,'Zero frequencies are allowed when selecting a valid rank.','Prefix counts remain nondecreasing, though not strictly increasing.'),
        (False,'The next block should be consumed when its cumulative count is equal to r.','Equality already reaches the requested rank; consume only strictly below.'),
        (True,'O(log u) binary-lifting selection needs nonnegative active frequencies.','Monotone prefixes justify discarding a block.'),
        (False,'Removing one occurrence of a duplicate means clearing that coordinate’s entire count.','Other active copies must remain.'),
        (True,'Whole-array compression can use future vocabulary while active counts still compute a current window statistic.','It is a batch representation, not an online O(k)-memory claim.'))],
      'q_l32_h1':[N('What is the actual original shortest s-to-c cost?',3,'Use s,b,a,c.'),N('What does permanent-settlement Dijkstra report for c?',4,'It settles a then c before b.'),N('What is the cost of the added b,a,c,b cycle?',-6,'Sum minus four, two and minus four.'),S('Select all valid conclusions.',
        (True,'Original DAG relaxation can handle the negative b→a edge.','All predecessor distances are available in topological order.'),
        (False,'Absence of a negative cycle suffices for the standard Dijkstra settlement proof.','This acyclic example already violates settlement.'),
        (True,'The added reachable negative cycle makes target shortest-walk cost unbounded below.','The cycle is on a source-to-target walk.'),
        (False,'Any negative cycle anywhere in a graph makes every target distance minus infinity.','Source reachability and a route from the cycle to the target are required.'),
        (True,'Allowing reopening changes the algorithm analysis rather than restoring the ordinary guarantee.','The nonnegative settlement proof no longer applies.'))],
      'q_l32_h2':[N('What is the original optimal compatible value?',14,'Jobs0,3,5 give14.'),N('What value does earliest-finish greedy obtain?',11,'Jobs1,2,4 give11.'),N('With appended job7 and skip-on-equality, how many selected jobs remain?',1,'The later three-job candidate ties the already chosen job7.'),S('Select all valid statements.',
        (True,'A job ending exactly when the next starts is compatible in this contract.','Intervals are half-open.'),
        (False,'The take transition may always use the optimum over every preceding sorted job.','That optimum can overlap the current job.'),
        (True,'A zero base case permits skipping all negative-value jobs.','Selecting nothing is allowed.'),
        (False,'Skip-on-equality universally minimizes the number of jobs among maximum-value schedules.','A secondary count objective must be modeled if required.'),
        (True,'Stable original indices must survive sorting and reconstruction.','The output identifies original records, not their sorted positions.'))]}
